export function sanitizeInput(input: string): string {
  const htmlEntities: [RegExp, string][] = [
    [/</g, '&lt;'],
    [/>/g, '&gt;'],
    [/"/g, '&quot;'],
    [/'/g, '&#039;']
  ];
  return htmlEntities.reduce((acc, [regex, entity]) => acc.replace(regex, entity), input);
}

